## Получение входных значений \{#receive-input-values\}

Входные значения поступают в тот же колбэк, что и все остальные аналитические события флоу, под именем события `flow_user_input`. Реализуйте `FlowViewDidReceiveAnalyticEvent` в слушателе, который вы регистрируете через `Adapty.SetFlowsEventsListener`:

```csharp showLineNumbers title="Unity"
public void FlowViewDidReceiveAnalyticEvent(
    AdaptyUIFlowView view,
    string name,
    IReadOnlyDictionary<string, object> parameters
) {
    HandleFlowInput(name, parameters);
}
```

h2-receive-input-values-pe3b0c442.translation:
```csharp showLineNumbers title="Unity"
private void HandleFlowInput(string name, IReadOnlyDictionary<string, object> parameters) {
    if (name != "flow_user_input") return;

    var elementId = parameters["element_id"] as string;

    // The screen the input sits on. Pair it with elementId to tell apart
    // two fields that share an Element ID on different screens.
    var screenId = parameters["instanceId"] as string;

    switch (parameters["element_type"] as string) {
        case "text_input":
        case "email_input":
        case "number_input":
        case "phone_input":
            var text = parameters["value"] as string;
            break;
        case "date_picker":
        case "time_picker":
        case "date_time_picker":
            // Unix time in milliseconds.
            var millis = Convert.ToInt64(parameters["value"]);
            break;
        case "single_choice":
            var optionId = (parameters["item_ids"] as JArray)?.First?.ToString();
            break;
        case "multi_choice":
            var optionIds = (parameters["item_ids"] as JArray)?.ToObject<List<string>>();
            break;
        case "toggle":
            var isOn = (bool)parameters["value"];
            break;
    }
}
```

